/**
 * warehouse-breakdown-tooltip.tsx
 * Solid-based tooltips for breaking down warehouse counts in a settlement
 */
import { createMemo, For, ParentComponent, Show, splitProps } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import {
	Tooltip,
	TooltipBaseProps,
	TooltipHorizontalPosition,
	TooltipVerticalPosition,
} from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import { WarehouseData } from "#base/ui/city-details/model-city-details.js";
import { EntryDivider, TicketSection } from "#base/ui-next/tooltips/plot-tooltip/components/utility.jsx";

interface WarehouseBreakdownTooltipProps
	extends Omit<TooltipBaseProps, "initialVPosition" | "initialHPosition" | "offset"> {
	initialVPosition?: TooltipVerticalPosition;
	initialHPosition?: TooltipHorizontalPosition;
	offset?: number;
	warehouseCounts: Map<string, WarehouseData>;
}

type WarehouseBreakdownEntry = [string, string, number, boolean, WarehouseBreakdownEntry[]?];

export const WarehouseBreakdownTooltipComponent: ParentComponent<WarehouseBreakdownTooltipProps> = (props) => {
	const isSmallScreen = useIsSmallScreen();
	const [local, other] = splitProps(props, ["children", "class", "warehouseCounts"]);
	const BULLET_CHAR = String.fromCodePoint(0x2022);
	const getWarehouseImprovements = createMemo(() => {
		const data: WarehouseBreakdownEntry[] = [];
		for (const improvementType of local.warehouseCounts) {
			const entry = improvementType[1];
			const showBreakdown = entry.breakdown && entry.breakdown.size > 1;
			const breakdownEntries: WarehouseBreakdownEntry[] = [];
			let allReplaced = true;

			if (entry.breakdown) {
				for (const childImprovementType of entry.breakdown) {
					const childEntry = childImprovementType[1];
					const isReplacing = childEntry.name != entry.name;
					if (!isReplacing) allReplaced = false;

					breakdownEntries.push([childEntry.name, childEntry.icon, childEntry.total, isReplacing]);
				}
			}

			data.push([entry.name, entry.icon, entry.total, showBreakdown || allReplaced, breakdownEntries]);
		}
		return data;
	});

	return (
		<Tooltip {...other}>
			<Tooltip.Trigger>{local.children}</Tooltip.Trigger>
			<Tooltip.Content class={local.class}>
				<Tooltip.Frame class={isSmallScreen() ? "max-w-128" : "max-w-96"}>
					<div class="flex flex-col items-stretch">
						<div class="flex flex-col gap-2 items-center">
							<L10n.Stylize
								class="font-title uppercase text-gradient-secondary"
								text={"LOC_UI_CITY_DETAILS_WAREHOUSE_BREAKDOWN_HEADER"}
							/>
							<L10n.Stylize
								class="text-xs font-body px-2"
								text={"LOC_UI_CITY_DETAILS_WAREHOUSE_BREAKDOWN_DESCRIPTION"}
							/>
						</div>
						<TicketSection class="mt-1 p-3 flex flex-col">
							<For each={getWarehouseImprovements()}>
								{(improvement, index) => (
									<>
										<Show when={index() > 0}>
											<EntryDivider class={isSmallScreen() ? "" : "my-2"} />
										</Show>
										<div class="flex flex-row items-center">
											<Icon
												class="size-8 mr-3"
												name={improvement[1]}
											/>
											<div class="flex flex-col grow">
												<div
													class="flex flex-row items-center"
													classList={{
														"text-sm": !isSmallScreen(),
														"text-xs": isSmallScreen(),
													}}
												>
													<L10n.Stylize
														class="text-secondary font-title uppercase tracking-100"
														text={improvement[0]}
													/>
													<div class="grow" />
													<L10n.Stylize
														class="ml-8 uppercase tracking-100"
														text={"LOC_UI_CITY_DETAILS_WAREHOUSE_BREAKDOWN_COUNT"}
														args={[improvement[2]]}
													/>
												</div>
												<Show when={improvement[3]}>
													<div class={`h-px flex-auto my-0\\.5 bg-accent-2 opacity-20`} />
													<For each={improvement[4]}>
														{(childImprovement) => (
															<div class="flex flex-row items-center grow text-xs text-accent-3">
																<div class="mr-2">{BULLET_CHAR}</div>
																<div class="flex flex-row items-center grow">
																	<L10n.Stylize text={childImprovement[0]} />
																	<div class="grow" />
																	<L10n.Stylize
																		class="ml-6"
																		text={
																			"LOC_UI_CITY_DETAILS_WAREHOUSE_BREAKDOWN_COUNT"
																		}
																		classList={{
																			"opacity-60": isSmallScreen(),
																		}}
																		args={[childImprovement[2]]}
																	/>
																</div>
															</div>
														)}
													</For>
												</Show>
											</div>
										</div>
									</>
								)}
							</For>
						</TicketSection>
					</div>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};

export const WarehouseBreakdownTooltip = ComponentRegistry.register({
	name: "WarehouseBreakdownTooltip",
	createInstance: WarehouseBreakdownTooltipComponent,
	images: ["blp:base_ticket-bg", "blp:shell_line-divider"],
});
